    class PointSubclass(Point):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.name = name
            self.fields = fields
            self.srid_map = srid_map

        def __repr__(self):
            return f"{self.name}({self.fields})"

        def __str__(self):
            return f"{self.name}({self.fields})"

        def __eq__(self, other):
            return self.name == other.name and self.fields == other.fields and self.srid_map == other.srid_map

        def __ne__(self, other):
